import React, { useState, useEffect } from "react";

const Corousel = () => {
  // State untuk mengelola halaman dan data
  const [page, setPage] = useState("Corousel");
  const [loading, setLoading] = useState(false);
  const [data, setData] = useState([]);

  // Simulasi pengambilan data berdasarkan halaman
  useEffect(() => {
    setLoading(true);
    // Simulasi fetch data
    setTimeout(() => {
      const mockData = [
        { id: 1, nama: "John Doe", nominal: "100" },
        { id: 2, nama: "Jane Smith", nominal: "200" },
      ];
      setData(mockData);
      setLoading(false);
    }, 1000);
  }, [page]);

  return (
    <div className="p-4">
      {/* Menu Tabs */}
      <div>
        <ul className="flex mb-4">
          {["Artikel", "Corousel", "Penghargaan", "Video", "PMB"].map((item) => (
            <li
              key={item}
              className={`mr-4 p-2 rounded-lg cursor-pointer ${
                page === item ? "bg-teal-700 text-white" : "bg-teal-500"
              }`}
            >
              <button onClick={() => setPage(item)}>
                {item.charAt(0).toUpperCase() + item.slice(1)}
              </button>
            </li>
          ))}
        </ul>
      </div>

      {/* Konten Tabel */}
      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4">
        {loading ? (
          <div className="col-span-3 text-center text-gray-500">Loading...</div>
        ) : data.length > 0 ? (
          <table className="min-w-full bg-white border border-teal-300 rounded-lg shadow">
            <thead className="bg-teal-700 text-white">
              <tr>
                <th className="px-6 py-3 text-left font-medium">No</th>
                <th className="px-6 py-3 text-left font-medium">Nama</th>
              </tr>
            </thead>
            <tbody>
              {data.map((row, index) => (
                <tr key={row.id}>
                  <td className="px-6 py-4">{index + 1}</td>
                  <td className="px-6 py-4">{row.nama}</td>
                </tr>
              ))}
            </tbody>
          </table>
        ) : (
          <div className="col-span-3 text-center text-gray-500">
            Tidak ada data untuk halaman "{page}".
          </div>
        )}
      </div>
    </div>
  );
};

export default Corousel;
